import { Component, OnInit } from '@angular/core';
import { MatDialog } from '@angular/material/dialog';
import { Router } from '@angular/router';
import { SecureStorageService } from '../../../core/services/storage/secure-storage.service';
import { NewsessionComponent } from '../newsession/newsession.component';
import { CommonModule } from '@angular/common';
import { SetupscreenComponent } from '../setupscreen/setupscreen.component';
import { TranslateModule } from '@ngx-translate/core';

@Component({
  selector: 'app-dashboard',
  standalone: true,
  imports: [CommonModule, SetupscreenComponent, TranslateModule],
  templateUrl: './dashboard.component.html',
  styleUrl: './dashboard.component.scss'
})
export class DashboardComponent implements OnInit {
  tab: string = 'R';
  sessions: any = [
    {
      'name': 'Session 1',
      'status': 'L',
      'connection': 'L'
    },
    {
      'name': 'Session 2',
      'status': 'E',
      'connection': 'EL'
    },
    {
      'name': 'Session 3',
      'status': 'S',
      'connection': 'S'
    },
  ]

  userInfo: any;

  constructor(private readonly dialog: MatDialog, private readonly router: Router, private readonly store: SecureStorageService) { }

  ngOnInit(): void {
    this.store.getUserInfo().then(userInfo => {
      this.userInfo = userInfo;
    });
  }

  newSession() {
    const dialogRef = this.dialog.open(NewsessionComponent,
      {
        width: '630px',
        height: 'fit-content'
      });

    dialogRef.afterClosed().subscribe(result => {
    });
  }

  join() {
    this.router.navigate(['realtime/livefeed']);
  }
}